def word_count(text):
    counts = {}
    for w in text.split(' '):
        # Normalize the word by lowercasing and removing punctuation
        normalized = ''.join(c for c in w if c.isalnum())
        normalized = normalized.lower()
        counts[normalized] = counts.get(normalized, 0) + 1
    return counts

