def index_of(xs, x):
    if not xs:
        return -1
    lo, hi = 0, len(xs)
    while lo < hi:
        mid = (lo + hi) // 2
        if xs[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo if xs[lo] == x else -1

