def merge(intervals):
    if not intervals:
        return []

    # Sort intervals by start time, then by end time
    intervals.sort(key=lambda x: (x[0], x[1]))

    merged = []

    for start, end in intervals:
        if not merged or merged[-1][1] < start:
            merged.append([start, end])
        else:
            merged[-1][1] = end

    return merged

